import{_ as o,l as i,o as e,c as s,v as t,p as n,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"LR 与移进归约","description":"","frontmatter":{"title":"LR 与移进归约","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lr-shift-reduce.md","filePath":"cs/lr-shift-reduce.md","lastUpdated":1789023840000}'),c={name:"cs/lr-shift-reduce.md"};function L(A,a,_,u,f,m){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="lr-与移进归约" tabindex="-1">LR 与移进归约 <a class="header-anchor" href="#lr-与移进归约" aria-label="Permalink to &quot;LR 与移进归约&quot;">​</a></h1><div class="epigraph"><p>自底向上：把已识别的右部归约成左端非终结符；移进把下一记号压栈，由项集决定动作。</p><footer>—— 据 Knuth, On the Translation of Languages from Left to Right, 1965；龙书第 4 章整理</footer></div><p>上一课<a href="/cs/ll-first-follow">LL 与 FIRST/FOLLOW</a>给出自上而下预测。许多无二义文法不是 LL(1)：左递归、公共前缀。本课不重算 FIRST。缺口是<strong>移进归约</strong>：栈上放已读前缀对应的项，动作由 DFA（项集规范族）决定。本课钉 LR 的直觉与冲突种类；不手填一张巨大的 SLR 表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最左归约的逆是最右推导。分析器维护栈：移进读记号；当栈顶形成某 \\(A\\to\\alpha\\) 的 \\(\\alpha\\) 且前瞻允许，则弹出 \\(|\\alpha|\\) 个符号、压 \\(A\\)。何时允许由项 \\(A\\to\\beta\\cdot\\gamma\\) 的闭包与转移给出。缺口是这份自底向上的控制，不是再写递归下降。</p><p>LR(1) 比 LL(1) 认的语言更广，仍是确定上下文无关语言的实用近全。二义文法（if-else）会移进/归约冲突，用优先级消解是工具习惯，本课承认。</p><h3 id="项不是产生式的别名" tabindex="-1">项不是产生式的别名 <a class="header-anchor" href="#项不是产生式的别名" aria-label="Permalink to &quot;项不是产生式的别名&quot;">​</a></h3><p>项记录「右部已经看到哪」。闭包把点后非终结符的所有产生式加进来，像 ε 转移。GOTO 是读一个符号后的新项集。这是词法 DFA 在文法上的同类物，状态却是项集。</p><p><span class="marginnote">Knuth 1965 定义 LR(\\(k\\))。DeRemer 的 SLR、LALR 是实用弱化。Yacc/bison 用 LALR(1)。本课不把四种表的包含关系证完，只认移进、归约、接受、报错。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从增广文法 \\(S&#39;\\to S\\) 建项集 DFA。表：动作（移进 \\(s_i\\)、归约 \\(A\\to\\alpha\\)、接受）与转移。分析循环查表直到接受或空动作。</p>',11)),(e(),n(p,null,{default:r(()=>[h(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%AE%B0%E5%8F%B7%22%5D%20--%3E%20SH%5B%22%E7%A7%BB%E8%BF%9B%22%5D%0A%20%20SH%20--%3E%20STK%5B%22%E6%A0%88%20%2B%20%E7%8A%B6%E6%80%81%22%5D%0A%20%20STK%20--%3E%20RED%5B%22%E5%BD%92%E7%BA%A6%20A%E2%86%92%CE%B1%22%5D%0A%20%20RED%20--%3E%20STK%0A%20%20STK%20--%3E%20ACC%5B%22%E6%8E%A5%E5%8F%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>SLR 用 FOLLOW 决定归约前瞻，可能冲突；LR(1) 把前瞻编进项。本课只要知道冲突 = 同一状态下移进与归约或两归约争同一记号。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>左递归对 LR 无妨，这是相对 LL 的实际收益。归约时执行语义动作、建 AST 节点，下一课接。分析仍线性于记号数（表已建好）。表的大小是编译器生成时的代价，不是源程序的渐近。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不列出全部闭包算法伪代码。不处理 GLR。二义消解规则不是 CFG 的一部分。后课默认：程序语言语法用 LR 族分析器；输出是分析树或直接 AST。抽象语法树丢掉推导里的纯形式节点。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LR = 移进归约 + 项集 DFA；认的语言宽于 LL(1)。</li><li>冲突是移进/归约或归约/归约。</li><li>左递归可保留；表在生成期构造。</li><li>出处：Knuth, 1965；Aho et al., 龙书第 4 章。</li></ul>',7))])}const E=o(c,[["render",L]]);export{S as __pageData,E as default};
